/* @lc app=leetcode id=3030 lang=kotlin */ class Solution { fun resultGrid(image: Array<IntArray>, threshold: Int): Array<IntArray> = image.size.let { m -> image[0].size.let { n -> Array(m) { IntArray(n) }.let { s -> Array(m) { IntArray(n) }.let { c -> (0..m - 3).forEach { i -> (0..n - 3).forEach { j -> if ((0..8).all { t -> (t / 3).let { r -> (t % 3).let { cc -> (cc == 2 || Math.abs(image[i + r][j + cc] - image[i + r][j + cc + 1]) <= threshold) && (r == 2 || Math.abs(image[i + r][j + cc] - image[i + r + 1][j + cc]) <= threshold) } } }) (0..8).sumOf { image[i + it / 3][j + it % 3] / 1 }.div(9).let { a -> (0..8).forEach { t -> s[i + t / 3][j + t % 3] += a.also { c[i + t / 3][j + t % 3]++ } } } } }.let { Array(m) { i -> IntArray(n) { j -> if (c[i][j] == 0) image[i][j] else s[i][j] / c[i][j] } } } } } } } }